 	\[
 		C^x_{g_1,\,g_2,\,\dots,\,g_k} = G^{k,\,x}_{g_k} \cdots G^{2,\,x}_{g_2}\; G^{1,\,x}_{g_1}\; G^{2,\,x}_{g_2} \cdots G^{k,\,x}_{g_k}\,;
