192	\section{The Magic Square game}
193	% Paper label sec:ms kept for cross-reference fidelity.
194	\label{sec:ms}
195	
196	We recall the Magic Square game of Mermin and Peres. It is a simple self-test for two EPR pairs, and it allows one to test that a pair of binary observables \emph{anticommutes}; both properties are used in the Pauli basis test. Here it is presented as a binary constraint satisfaction game. Throughout this section and the next, $\sigma^X$ and $\sigma^Z$ denote the single-qubit Pauli observables, with associated two-outcome projective measurements $\{\sigma^W_b\}_{b \in \F_2}$ for $W \in \{X,Z\}$.
197	
198	\begin{definition}[The Magic Square game]\label{def:ms-game}
199		\uses{def:game, def:graph-distribution}
200		The Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ is the following two-player game. There are $9$ variables $x_1,\ldots,x_9$ taking values in $\F_2$, arranged in a $3 \times 3$ grid: the cell in row $r$ and column $c$ contains the variable $x_{3(r-1)+c}$. There are $6$ linear equations over these variables: for each of the three rows and each of the first two columns, the sum of the three variables in it equals $0$; for the third column, the sum of the three variables in it equals $1$.
360		\end{itemize}
361		The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
362		\begin{equation}
363			\label{eq:gamma-value}
364			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
365		\end{equation}
366		where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
367		\begin{enumerate}
368			\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
369			\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$; admissibility of $\mathsf{qldparams}$ gives $d \ge 1$ and $m \mid q$, so this is a parameter tuple as in Definition~\ref{def:ld-game}.
370			\begin{enumerate}
371				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
372				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
373			\end{enumerate}
374			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
375			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
376			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
377			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
378			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
379		\end{enumerate}
380		The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
381	\end{definition}
